/** Canonicaliza SOLO alias explícitos que la RPC de catálogos D013 ya admite.
 * El original queda intacto en p_original_text; no afecta Córdoba, Berisso
 * ni otras localidades. SQL de preparación/publicación usa ciudad canónica.
 */
const LA_PLATA_D013=new Set([
 'la plata',
 'la plata, buenos aires',
 'la plata, buenos aires, argentina',
 'la plata, provincia de buenos aires',
 'la plata, provincia de buenos aires, argentina'
]);
export function localidadOperativaD013(ciudad:string):string{
 const literal=ciudad.trim();
 const normalized=literal.normalize('NFD').replace(/[\u0300-\u036f]/gu,'')
  .toLowerCase().replace(/\s+/gu,' ');
 return LA_PLATA_D013.has(normalized)?'La Plata':literal;
}
/** Adaptar el lector libre al esquema V2 ya publicado, SIN inventar
 * envases ni convertir peso a volumen. El texto original se almacena
 * íntegro y la descripción siempre conserva la presentación literal.
 */
export function cantidadUnidadSqlV2D013(
 cantidad:string,unidad:string
):Readonly<{cantidad:string;unidad:string}>|null{
 if(typeof cantidad!=='string'||! /^(?:0|[1-9]\d{0,5})(?:\.\d{1,3})?$/u.test(cantidad)||
    !(Number(cantidad)>0)||typeof unidad!=='string'||unidad.length>80)
  return null;
 const canonical=unidadCompradaCanonicaV2D013(unidad);
 // El catálogo SQL conserva "bolsón" dentro de la descripción original.
 // Ambos son conteos de envases, no un volumen asumido.
 if(canonical==='bigbag')return {cantidad,unidad:'bag'};
 if(canonical==='bucket')return {cantidad,unidad:'unit'};
 const supported=new Set(['unit','bag','box','kg','g','l','ml',
  'm','m2','m3','roll','pack']);
 if(supported.has(canonical))return {cantidad,unidad:canonical};
 const measure=unidadDimensionadaV2D013(unidad);
 if(!measure)return null;
 const target=measure.dimension==='longitud'?'m':
  measure.dimension==='superficie'?'m2':
  measure.dimension==='volumen_aridos'?'m3':
  measure.dimension==='volumen_liquidos'?'l':'kg';
 const [entero,decimal='']=cantidad.split('.');
 const mil=BigInt(entero)*1000n+BigInt(decimal.padEnd(3,'0'));
 const converted=mil*measure.factor;
 if(converted%1000000000n!==0n)return null;
 const quotient=converted/1000000000n;
 if(quotient<=0n||quotient>1000000000n)return null;
 const base=quotient/1000n,frac=quotient%1000n;
 const normalized=frac===0n?base.toString():
  base.toString()+'.'+frac.toString().padStart(3,'0').replace(/0+$/u,'');
 return {cantidad:normalized,unidad:target};
}

type Params=Readonly<{
 p_buyer_chat_hmac:string;p_message_hmac:string;
 p_original_text:string;p_city:string;
 p_items:readonly Readonly<{
  descripcion:string;cantidad:string;unidad:string;
  evidencia:string;rubro:string
 }>[];
 p_destinos:readonly Readonly<{
  proveedor:string;
  correspondencias:readonly Readonly<{
   indicePedido:number;numeroCatalogo:number;
   descripcionCatalogo:string;rubroCatalogo:string;
   tipo:'producto_declarado'|'alternativa_razonable';
   explicacion:string
  }>[];
 }>[];
}>;
export type ResultadoPuenteMvp221=Readonly<{
 estado:'plan_sql_listo'|'plan_no_verificable';
 motivo:string;params:Params|null;
}>;
const no=(motivo:string):ResultadoPuenteMvp221=>({
 estado:'plan_no_verificable',motivo,params:null
});
/** Convertir coincidencia IA a referencia exacta del catálogo.
 * Si cambió la fuente, el SQL rechaza la escritura (CAS por descripción).
 */
export function armarPreparacionSombraMvp221(args:{
 chatHmac:string;messageHmac:string;textoOriginal:string;
 autenticadoPorWebhook:boolean;
 plan:PlanMvp220;multifuente?:boolean;distribucionComercial?:boolean
}):ResultadoPuenteMvp221{
 if(!args||args.autenticadoPorWebhook!==true||
    !HASH.test(args.chatHmac)||!HASH.test(args.messageHmac)||
    typeof args.textoOriginal!=='string'||
    args.textoOriginal.length<10||args.textoOriginal.length>(args.multifuente?12000:4000)||
    args.plan?.estado!=='plan_validado_sin_envio'||
    args.plan.whatsappEnviado!==false||args.plan.baseModificada!==false||
    !args.plan.pedido||!Array.isArray(args.plan.pedido.articulos)||
    !args.plan.ruteo||args.plan.ruteo.estado!=='ruteo_valido_para_preparacion'||
    !Array.isArray(args.plan.catalogos))
  return no('origen_o_plan_no_verificado');
 const {pedido,ruteo}=args.plan;
 if(typeof pedido.zona_entrega!=='string'||pedido.zona_entrega.length<3||
    pedido.articulos.length<1||pedido.articulos.length>200)
  return no('ciudad_o_items_invalidos');
 const bySupplier=new Map<string,ProveedorCatalogoV2>(
  args.plan.catalogos.map(s=>[s.clave,s] as const)
 );
 if(bySupplier.size!==args.plan.catalogos.length)return no('proveedores_duplicados');
 const items=pedido.articulos.map((item,i)=>{
  const representada=cantidadUnidadSqlV2D013(item.cantidad,item.unidad);
  return {
   descripcion:descripcionFuenteV2D013(args.textoOriginal,item,
    pedido.articulos[i+1]?.inicio),
   cantidad:representada?.cantidad??null,unidad:representada?.unidad??null,
   evidencia:item.evidencia,rubro:item.rubro
  };
 });
 // Conservar todas las especificaciones originales; el límite SQL es 500.
 // La renderización PDF ocurre DESPUÉS y no decide si el pedido es válido.
 if(items.some(x=>x.descripcion===null))
  return no('presentacion_fuente_no_representable');
 if(items.some(x=>x.cantidad===null||x.unidad===null))
  return no('cantidad_unidad_no_representable_en_sql');
 const fullItems=items as ReadonlyArray<{
  descripcion:string;cantidad:string;unidad:string;
  evidencia:string;rubro:string
 }>;
 const seen=new Set<string>();
 const destinations:Params['p_destinos'][number][]=[];
 for(const destination of ruteo.propuestas){
  if(!KEY.test(destination.proveedor)||seen.has(destination.proveedor))
   return no('destinatario_duplicado_o_invalido');
  const source=bySupplier.get(destination.proveedor);
  if(!source||!source.consentido||!source.activo||
     destination.correspondencias.length<1)
   return no('catalogo_no_confirmado');
  const matches:Params['p_destinos'][number]['correspondencias'][number][]=[];
  const positions=new Set<number>();
  for(const match of destination.correspondencias){
   if(!Number.isSafeInteger(match.indicePedido)||
      match.indicePedido<0||match.indicePedido>=fullItems.length||
      !Number.isSafeInteger(match.numeroCatalogo)||
      positions.has(match.indicePedido))return no('indice_de_pedido_invalido');
   const row=source.articulos.find(x=>x.numero===match.numeroCatalogo);
   if(!row||
      !['producto_declarado','alternativa_razonable'].includes(match.tipo)||
      typeof match.explicacion!=='string'||
      match.explicacion.length<3||match.explicacion.length>240)
    return no('catalogo_sin_evidencia');
   positions.add(match.indicePedido);
   matches.push({
    indicePedido:match.indicePedido,
    numeroCatalogo:match.numeroCatalogo,
    descripcionCatalogo:row.descripcion,
    rubroCatalogo:row.rubro,
    tipo:match.tipo,explicacion:match.explicacion
   });
  }
  seen.add(destination.proveedor);
  destinations.push({proveedor:destination.proveedor,
   correspondencias:matches});
 }
 if(destinations.length<1||destinations.length>(args.multifuente===true&&args.distribucionComercial===true?70:25))return no('sin_destinos');
 return {estado:'plan_sql_listo',motivo:'identificadores_y_citas_del_catalogo',
  params:{
   p_buyer_chat_hmac:args.chatHmac,
   p_message_hmac:args.messageHmac,
   p_original_text:args.textoOriginal,
   p_city:localidadOperativaD013(pedido.zona_entrega),
   p_items:fullItems,p_destinos:destinations
  }};
}
type DbResponse={data:unknown;error:unknown};
/** Solo ejecuta una RPC cuya implementación no puede despachar.
 * No exponer request_id, catálogo ni token de WhatsApp en web o logs.
 */
export async function guardarRondaSombraMvp221(
 prepared:ResultadoPuenteMvp221,
 rpc:(name:string,params:Params)=>Promise<DbResponse>
):Promise<Readonly<{estado:'guardado'|'ya_existia'|'rechazado';
 motivo:string;articulos:number;matches:number}>>{
 const error=(motivo:string)=>({estado:'rechazado' as const,
  motivo,articulos:0,matches:0});
 if(prepared?.estado!=='plan_sql_listo'||!prepared.params||
    typeof rpc!=='function')return error('plan_no_preparado');
 try{
  // V2-21: solo RPC V2 aislada. Nunca modificar/ejecutar M221 histórico.
  const result=await rpc('cotironda_piloto_v2_shadow_prepare_d013',
   prepared.params);
  if(result.error!==null&&result.error!==undefined)
   return error('sql_no_disponible');
  const d=result.data;
  if(!d||typeof d!=='object'||Array.isArray(d))
   return error('sql_no_conciliado');
  const body=d as Record<string,unknown>;
  if(body.state==='already_staged')
   return {estado:'ya_existia',motivo:'idempotencia_por_mensaje',
    articulos:0,matches:0};
  const expected=prepared.params;
  const lines=expected.p_items.length;
  const matches=expected.p_destinos.reduce(
   (sum,d)=>sum+d.correspondencias.length,0);
  if(body.state!=='shadow_staged'||body.items_staged!==lines||
     body.matches_staged!==matches||body.invitations_sent!==0||
     body.outbox_sent!==0)return error('sql_resultado_incoherente');
  return {estado:'guardado',motivo:'ronda_sombra_verificada',
   articulos:lines,matches};
 }catch{return error('sql_no_disponible')}
}

import {validarSnapshotCatalogosMvp220,type SnapshotRealMvp220,type CatalogoRealMvp220,type ResultadoContextoMvp220} from './catalogo-supabase-mvp220.ts';
import {categorizarCatalogosCuradosD013} from './catalogo-curado-v2-d013.ts';
import type {ProveedorCatalogoV2} from './ruteador-catalogos-v2-d013.ts';

/** V2 comercial solamente. Reutiliza el validador legado en grupos completos.
 * 200 candidatos consultables NO significa 200 invitaciones. No filtra por rubro. */
export function validarSnapshotCatalogosComercialesV2(input:unknown):SnapshotRealMvp220|null{
 const base=validarSnapshotCatalogosMvp220(input);
 if(base)return base;
 if(!input||typeof input!=='object'||Array.isArray(input))return null;
 const raw=input as Record<string,unknown>;
 if(raw.estado!==undefined||raw.state!=='catalogue_snapshot'||!Array.isArray(raw.proveedores)||
    raw.proveedores.length<26||raw.proveedores.length>200||
    !Number.isSafeInteger(raw.proveedoresSinConfirmar)||Number(raw.proveedoresSinConfirmar)<0)return null;
 const all:CatalogoRealMvp220[]=[];
 const seen=new Set<string>();
 let city='';
 let unconfirmed=0;
 for(let i=0;i<raw.proveedores.length;i+=25){
  const rows=raw.proveedores.slice(i,i+25);
  const localCount=rows.filter(x=>x&&x.catalogoConfirmado===false).length;
  const verified=validarSnapshotCatalogosMvp220({...raw,proveedores:rows,proveedoresSinConfirmar:localCount});
  if(!verified||city&&verified.localidad!==city)return null;
  city=verified.localidad;
  for(const supplier of verified.proveedores){
   if(seen.has(supplier.clave))return null;
   seen.add(supplier.clave);all.push(supplier);
  }
  unconfirmed+=verified.proveedoresSinConfirmar;
 }
 if(unconfirmed!==raw.proveedoresSinConfirmar||all.length!==raw.proveedores.length)return null;
 return {estado:'catalogue_snapshot',localidad:city,proveedores:all,proveedoresSinConfirmar:unconfirmed};
}

export async function categorizarCatalogosComercialesV2(args:Parameters<typeof categorizarCatalogosCuradosD013>[0]):Promise<ResultadoContextoMvp220>{
 const {snapshot}=args;
 if(snapshot.proveedores.length<=25)return categorizarCatalogosCuradosD013(args);
 const invalid=():ResultadoContextoMvp220=>({estado:'catalogo_invalido',motivo:'catalogo_comercial_no_conciliado',proveedores:[],sinConfirmar:0});
 if(snapshot.proveedores.length>200)return invalid();
 const all:ProveedorCatalogoV2[]=[];
 const seen=new Set<string>();let unconfirmed=0;
 for(let i=0;i<snapshot.proveedores.length;i+=25){
  const suppliers=snapshot.proveedores.slice(i,i+25);
  const count=suppliers.filter(x=>!x.catalogoConfirmado).length;
  const result=await categorizarCatalogosCuradosD013({...args,snapshot:{...snapshot,proveedores:suppliers,proveedoresSinConfirmar:count}});
  if(result.estado==='catalogo_invalido'||result.proveedores.length!==suppliers.length||result.sinConfirmar!==count)return invalid();
  for(const supplier of result.proveedores){
   if(seen.has(supplier.clave)||!suppliers.some(x=>x.clave===supplier.clave))return invalid();
   seen.add(supplier.clave);all.push(supplier);
  }
  unconfirmed+=count;
 }
 if(all.length!==snapshot.proveedores.length||unconfirmed!==snapshot.proveedoresSinConfirmar)return invalid();
 return {estado:unconfirmed?'catalogo_sin_confirmar':'catalogo_apto',motivo:unconfirmed?'falta_confirmacion_de_al_menos_un_catalogo':'catalogo_completo_con_fuente',proveedores:all,sinConfirmar:unconfirmed};
}

export function planificarLotesComerciales(pedido,proveedores,remaining){
 if(!Number.isSafeInteger(remaining)||remaining<1||remaining>32||
    !Array.isArray(pedido?.articulos)||pedido.articulos.length<1||pedido.articulos.length>25||
    !Array.isArray(proveedores)||proveedores.length<1||proveedores.length>200)return null;
 const seen=new Set(), groups=[];
 let group=[],chars=0;
 const itemCount=pedido.articulos.length;
 const baseChars=JSON.stringify(pedido.articulos).length;
 const flush=()=>{if(group.length)groups.push(group);group=[];chars=0;};
 for(const supplier of proveedores){
  if(!supplier||typeof supplier.clave!=='string'||seen.has(supplier.clave)||
     !Array.isArray(supplier.articulos)||supplier.articulos.length<1||supplier.articulos.length>150)return null;
  seen.add(supplier.clave);
  const size=JSON.stringify({clave:supplier.clave,catalogo:supplier.articulos}).length;
  if(size+baseChars>65000)return null;
  if(group.length>=25||(group.length+1)*itemCount>200||chars+size+baseChars>65000)flush();
  group.push(supplier);chars+=size;
 }
 flush();
 return groups.length<=remaining?groups:null;
}

export async function ejecutarLotesComerciales({pedido,proveedores,remainingCalls,deadlineMs,route,authorize,now=Date.now}){
 const fail=motivo=>({estado:'requiere_revision',motivo,propuestas:[],cobertura:[],revisionTecnica:[],whatsappEnviado:false});
 const eligible=proveedores;
 const baseline=authorize(pedido,eligible,[]);
 if(baseline.estado!=='ruteo_valido_para_preparacion'||baseline.cobertura.length!==pedido.articulos.length)
  return fail('catalogo_comercial_invalido');
 const groups=planificarLotesComerciales(pedido,eligible,remainingCalls());
 if(!groups)return fail('ruteo_comercial_presupuesto_insuficiente');
 if(!Number.isFinite(deadlineMs)||deadlineMs<=now())return fail('ruteo_comercial_plazo_insuficiente');
 const accepted=[],review=[];
 const successCodes=new Set(['productos_en_catalogo_y_zona_comprobados','coincidencias_requieren_correccion','coincidencias_parciales_verificadas','equivalencias_no_demostradas_en_revision_interna']);
 for(let i=0;i<groups.length;i++){
  // El medidor real no permite otra reserva mientras una esté abierta.
  // No paralelizar, ni iniciar un lote que no cabe en el plazo del lease.
  if(remainingCalls()<groups.length-i||deadlineMs-now()<60000)
   return fail('ruteo_comercial_presupuesto_o_plazo_agotado');
  let result;
  try{result=await route(pedido,groups[i]);}catch{return fail('lote_comercial_no_verificable')}
  if(!result||result.whatsappEnviado!==false||!successCodes.has(result.motivo)||
     !Array.isArray(result.propuestas)||!Array.isArray(result.revisionTecnica)||
     result.cobertura?.length!==pedido.articulos.length)
   return fail('lote_comercial_no_verificable');
  const checked=authorize(pedido,groups[i],result.propuestas);
  if(checked.estado!=='ruteo_valido_para_preparacion'||checked.propuestas.length!==result.propuestas.length||
     checked.propuestas.reduce((n,x)=>n+x.correspondencias.length,0)!==result.propuestas.reduce((n,x)=>n+x.correspondencias.length,0))
   return fail('lote_comercial_no_verificable');
  accepted.push(...result.propuestas);review.push(...result.revisionTecnica);
 }
 const final=authorize(pedido,eligible,accepted);
 if(final.estado!=='ruteo_valido_para_preparacion'||final.propuestas.length!==accepted.length)
  return fail('ruteo_comercial_no_conciliado');
 // Preservar explicación fija original (el autorizador añade prefijo a alternativas).
 return {...final,propuestas:accepted,revisionTecnica:review,
  estado:!accepted.length&&review.length?'requiere_revision':'ruteo_valido_para_preparacion',
  motivo:review.length?(accepted.length?'coincidencias_parciales_verificadas':'coincidencias_requieren_correccion'):final.motivo};
}

/** One resumable routing step. Caller must encrypt and bind buyer, conversation, revision, manifest and cursor to AAD; SQL CAS commits and requeues. */
export function iniciarCheckpointComercial({pedido,grupos,meta,manifest}){
 if(!pedido||!Array.isArray(pedido.articulos)||!Array.isArray(grupos)||!grupos.length||grupos.length>200||!/^[a-f0-9]{64}$/.test(manifest)||!meta)return null;
 const keys=grupos.flat().map(x=>x.clave);
 if(!keys.length||new Set(keys).size!==keys.length)return null;
 return {version:1,pedido,grupos,meta,manifest,cursor:0,resultados:[]};
}
export async function avanzarCheckpointComercial({snapshot,manifest,route,authorize,remainingCalls,deadlineMs,now=Date.now}){
 const fail=motivo=>({estado:'sin_avance',motivo});
 if(!snapshot||snapshot.version!==1||snapshot.manifest!==manifest||!Number.isSafeInteger(snapshot.cursor)||snapshot.cursor<0||!Array.isArray(snapshot.grupos)||!Array.isArray(snapshot.resultados)||snapshot.resultados.length!==snapshot.cursor||snapshot.cursor>snapshot.grupos.length)return fail('snapshot_invalido');
 const {pedido,grupos,cursor}=snapshot;
 const all=grupos.flat(),keys=all.map(x=>x.clave);
 if(new Set(keys).size!==keys.length)return fail('snapshot_invalido');
 const checked=authorize(pedido,all,[]);
 if(checked.estado!=='ruteo_valido_para_preparacion'||checked.cobertura.length!==pedido.articulos.length)return fail('catalogo_invalido');
 const success=new Set(['productos_en_catalogo_y_zona_comprobados','coincidencias_requieren_correccion','coincidencias_parciales_verificadas','equivalencias_no_demostradas_en_revision_interna']);
 const valid=(result,group)=>{
  if(!result||result.whatsappEnviado!==false||!success.has(result.motivo)||!Array.isArray(result.propuestas)||!Array.isArray(result.revisionTecnica)||result.cobertura?.length!==pedido.articulos.length)return false;
  const verified=authorize(pedido,group,result.propuestas);
  return verified.estado==='ruteo_valido_para_preparacion'&&verified.propuestas.length===result.propuestas.length&&verified.propuestas.reduce((n,x)=>n+x.correspondencias.length,0)===result.propuestas.reduce((n,x)=>n+x.correspondencias.length,0);
 };
 if(snapshot.resultados.some((res,i)=>!valid(res,grupos[i])))return fail('snapshot_resultado_invalido');
 if(cursor===grupos.length){
  const proposals=snapshot.resultados.flatMap(r=>r.propuestas);
  const final=authorize(pedido,all,proposals);
  if(final.estado!=='ruteo_valido_para_preparacion'||final.propuestas.length!==proposals.length)return fail('resultado_no_conciliado');
  const revisionTecnica=snapshot.resultados.flatMap(r=>r.revisionTecnica);
  return {estado:'completo',resultado:{...final,propuestas:proposals,revisionTecnica,estado:!proposals.length&&revisionTecnica.length?'requiere_revision':final.estado},snapshot};
 }
 if(!Number.isFinite(deadlineMs)||deadlineMs-now()<120000||remainingCalls()<2)return fail('presupuesto_o_plazo_insuficiente');
 let result;
 try{result=await route(pedido,grupos[cursor]);}catch{return fail('lote_no_verificable')}
 if(!valid(result,grupos[cursor]))return fail('lote_no_verificable');
 return {estado:'guardar',expected:cursor,snapshot:{...snapshot,cursor:cursor+1,resultados:[...snapshot.resultados,result]}};
}

/** MVP264: OpenAI Responses metering for an ALREADY authorized IA Central
 * source. 100% opt-in in the broker. Never stores prompts or responses,
 * only usage numbers and a SHA-256 of the opaque API response identifier.
 * Reserved/unknown usage is NOT zero cost; future paid calls fail closed.
 */
type Rpc=(name:string,params:Record<string,unknown>)=>
 Promise<{data:unknown;error:unknown}>;
type Model='gpt-6-luna'|'gpt-6.1-sol';
type Role='buyer'|'supplier';
const API='https://api.openai.com/v1/responses';
const SHA=/^[a-f0-9]{64}$/u;
const isObj=(x:unknown):x is Record<string,unknown>=>
 x!==null&&typeof x==='object'&&!Array.isArray(x);
const safe=(n:unknown,max=600000):n is number=>
 typeof n==='number'&&Number.isSafeInteger(n)&&n>=0&&n<=max;
function usageOf(raw:unknown){
 if(!isObj(raw)||typeof raw.id!=='string'||!/^resp_[a-zA-Z0-9_-]{8,160}$/u.test(raw.id)
  ||!isObj(raw.usage))return null;
 const u=raw.usage;
 if(!safe(u.input_tokens,300000)||!safe(u.output_tokens,300000)||
  !safe(u.total_tokens)||u.total_tokens!==u.input_tokens+u.output_tokens)
  return null;
 return {id:raw.id,input:u.input_tokens,output:u.output_tokens,total:u.total_tokens};
}
async function sha(source:string){
 const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(source));
 return Array.from(new Uint8Array(bytes)).map(x=>x.toString(16).padStart(2,'0')).join('');
}
export function instrumentoOpenAiMvp264(args:{
 messageHmac:string;chatHmac:string;role:Role;model:Model;
 rpc:Rpc;fetchImpl?:typeof fetch;initialCallNo?:number;
 commercialScope?:{id:string;revision:number;lease:string};onCallNo?:(n:number)=>void;
}):typeof fetch{
 if(!SHA.test(args.messageHmac)||!SHA.test(args.chatHmac)
  ||!['buyer','supplier'].includes(args.role)||
  !['gpt-6-luna','gpt-6.1-sol'].includes(args.model))
  throw Error('mvp264_invalid_identity');
 const scope=args.commercialScope;
 const uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iu;
 if(scope&&(args.role!=='buyer'||!uuid.test(scope.id)||!uuid.test(scope.lease)||!Number.isSafeInteger(scope.revision)||scope.revision<1))
  throw Error('mvp264_invalid_commercial_scope');
 const max=scope?32:args.role==='buyer'?8:2;
 let callNo=args.initialCallNo??0;
 if(!Number.isSafeInteger(callNo)||callNo<0||callNo>=max)throw Error('mvp264_invalid_call_sequence');
 const db=async(name:string,params:Record<string,unknown>)=>{
  const r=await args.rpc(name,params);
  if(r.error!==null&&r.error!==undefined||!isObj(r.data)||
   typeof r.data.state!=='string')
   throw Error('mvp264_ledger_unavailable');
  return r.data;
 };
 return (async(input:RequestInfo|URL,init?:RequestInit):Promise<Response>=>{
  if(typeof input!=='string'||input!==API||init?.method!=='POST'||
   callNo>=max||typeof init.body!=='string')
   throw Error('mvp264_call_outside_budget');
