   p_call_no:seq};
  const pre=await db(scope?'cotironda_piloto_v2_commercial_usage_reserve':'cotironda_piloto_ai_usage_reserve_mvp264',{
   ...fields,p_model:args.model,...(scope?{p_id:scope.id,p_revision:scope.revision,p_lease:scope.lease}:{})
  });
