 }
 const commercial=io.commercialEnabled===true;
 const checkpointArgs={rpc:call,fields,io,chat,id,revision:g.revision};
 const loaded=commercial?await cargarComercial(checkpointArgs):null;
 const saved=loaded?.snapshot??null;
 const meter=await call(saved?'cotironda_piloto_v2_commercial_meter':'cotironda_piloto_v2_conversation_meter',fields);
 if(meter.state==='meter_busy'||meter.state==='stale')return String(meter.state);
