   apiKey:io.apiKey,model:io.model,rpc:io.rpc,
   fetchImpl:meteredFetch,
   ...(commercial?{rubrosComerciales:true,diferirComercial:true}:{}),
   ...(resumed?{pedidoContinuado:resumed.pedido,localidadConfirmada:resumed.city}:{}),
   onConversacion:meta=>{
    latestMeta={pago:meta.pago,iva:meta.iva};
    const conditions=condicionesSolicitudV2(context,cite(meta.pago),cite(meta.iva));
    payment=conditions.pago.evidencia&&meta.pago!==null?{literal:meta.pago,message_hmac:conditions.pago.evidencia.messageHmac}:null;
    vat=conditions.iva.evidencia&&meta.iva!==null?{literal:meta.iva,message_hmac:conditions.iva.evidencia.messageHmac}:null;
    metaSeen=true;
   }
  });
  if(commercial&&plan.estado==='ruteo_diferido'&&plan.pedido&&plan.catalogos&&metaSeen){
   const groups=planificarLotesComerciales(plan.pedido,plan.catalogos,Math.floor((32-callNo)/2));
   if(!groups||!loaded)return finish('review','conversation_processing_unavailable');
   const snapshot=iniciarCheckpointComercial({pedido:plan.pedido,grupos:groups,manifest:loaded.manifest,meta:{context,payment,vat}});
   if(!snapshot)return finish('review','conversation_processing_unavailable');
   return await guardarComercial({...checkpointArgs,snapshot,expected:-1,pause:true});
  }
  if(plan.motivo==='conversation_waiting')return finish('awaiting_context','conversation_waiting');
  if(plan.motivo==='conversation_multiple_orders')return finish('awaiting_context','conversation_multiple_orders');
  if(plan.motivo==='zona_de_entrega_faltante'||plan.motivo==='falta_localidad'){
   const body='¿En qué localidad se entregan los materiales?';
   if(plan.pedido&&plan.pedido.zona_entrega===null&&latestMeta){
    const enc=await io.encrypt(JSON.stringify({pedido:plan.pedido,meta:latestMeta,prefixSha:await io.sha(context.texto)}),aad(g.revision));
    const r=await call('cotironda_piloto_v2_conversation_save_zone',{...fields,p_message_hmac:last,p_nonce:enc.nonce,p_ciphertext:enc.ciphertext});
    if(r.state==='awaiting_context'&&r.reply_reserved===true)await io.sendClarification(id,chat,last,body);
    return String(r.state);
   }
   return finish('awaiting_context','delivery_city_missing',{code:'zone',body});
  }
  if(plan.motivo==='ia_central_solicita_aclaracion'&&plan.pregunta)
   return finish('awaiting_context','ia_central_solicita_aclaracion',{code:'materials',body:plan.pregunta});
  if(plan.estado!=='plan_validado_sin_envio'||!plan.pedido||!metaSeen)
   return finish('review',metaSeen?codigoRevisionSemanticaMvp286(plan.motivo):'conversation_metadata_missing');
  let rubros:unknown[]= [];
  if(commercial){
   const selection=await seleccionarPlanComercial({plan,rpc:io.rpc,selector:seleccionarComercialD013,authorize:autorizarPropuestasCatalogoV2});
   if(!selection)return finish('review','conversation_processing_unavailable');
   plan=selection.plan;rubros=selection.rubros;
  }
  const prepared=armarPreparacionSombraMvp221({chatHmac:chat,messageHmac:first,textoOriginal:context.texto,autenticadoPorWebhook:true,plan,multifuente:true,distribucionComercial:commercial});
  if(prepared.estado!=='plan_sql_listo'||!prepared.params)
   return finish('review',codigoRevisionPuenteV2D013(prepared.motivo));
  const p=prepared.params;
  const fragments=context.tramos.map(t=>({message_hmac:t.messageHmac,text:context.texto.slice(t.inicio,t.fin),...(t.mediaSha256?{media_sha256:t.mediaSha256,derived_sha256:t.derivedSha256}:{})}));
  const stage=await call(commercial?'cotironda_piloto_v2_commercial_stage':'cotironda_piloto_v2_conversation_stage',{p_buyer_chat_hmac:chat,p_id:id,p_revision:g.revision,p_lease:g.lease,p_fragments:fragments,p_city:p.p_city,p_items:p.p_items,p_destinos:p.p_destinos,p_payment:payment,p_vat:vat,...(commercial?{p_rubros:rubros}:{})});
  if(stage.state==='stale')return 'stale';
  if(!['shadow_staged','already_staged'].includes(String(stage.state)))return finish('review','conversation_stage_rejected');
  return finish('staged','conversation_staged');
 }catch{
  // A lost staging response may already have created a draft. Its delivery
  // is reconciled by SQL, not by repeating the model or recreating a round.
  try{await finish('review','conversation_processing_unavailable')}catch{/* lease recovery */}
  return 'processing_unavailable';
 }
}

