-- CANDIDATE, not installed. Reuse existing claim/tick, no new cron or transport.
CREATE TABLE cotironda_piloto_privado.v2_commercial_route_checkpoint (
 conversation_id uuid PRIMARY KEY REFERENCES cotironda_piloto_privado.v2_buyer_conversations(id) ON DELETE CASCADE,
 revision bigint NOT NULL CHECK(revision>0),
 manifest_sha text NOT NULL CHECK(manifest_sha~'^[a-f0-9]{64}$'),
 cursor_no integer NOT NULL CHECK(cursor_no BETWEEN 0 AND 200),
 total_groups integer NOT NULL CHECK(total_groups BETWEEN 1 AND 200 AND cursor_no<=total_groups),
 nonce text NOT NULL CHECK(nonce~'^[A-Za-z0-9+/]{16}$'),
 ciphertext text NOT NULL CHECK(length(ciphertext) BETWEEN 24 AND 16777216 AND ciphertext~'^[A-Za-z0-9+/=]+$'),
 expires_at timestamptz NOT NULL
);
ALTER TABLE cotironda_piloto_privado.v2_commercial_route_checkpoint ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON cotironda_piloto_privado.v2_commercial_route_checkpoint FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.cotironda_piloto_v2_commercial_checkpoint(
 p_chat_hmac text,p_id uuid,p_revision bigint,p_lease uuid,
 p_action text,p_expected integer,p_total integer,p_manifest text,p_nonce text,p_ciphertext text,p_pause boolean
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $checkpoint$
DECLARE b text; g cotironda_piloto_privado.v2_buyer_conversations%ROWTYPE;
 old cotironda_piloto_privado.v2_commercial_route_checkpoint%ROWTYPE;
 manifest text; cursor_next integer;
BEGIN
 IF p_action IS NULL OR p_action NOT IN ('load','save') THEN RETURN jsonb_build_object('state','invalid'); END IF;
 SELECT key INTO b FROM cotironda_piloto_privado.participants WHERE chat_hmac=p_chat_hmac AND participant_role='buyer' AND consent_at IS NOT NULL AND opted_out_at IS NULL FOR UPDATE;
 IF b IS NULL THEN RETURN jsonb_build_object('state','not_authorized'); END IF;
 SELECT * INTO g FROM cotironda_piloto_privado.v2_buyer_conversations WHERE id=p_id AND buyer_key=b AND chat_hmac=p_chat_hmac AND revision=p_revision AND state='processing' AND lease=p_lease AND lease_until>clock_timestamp() AND request_id IS NULL FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('state','stale'); END IF;
 IF EXISTS(SELECT 1 FROM cotironda_piloto_privado.v2_buyer_conversation_sources s LEFT JOIN cotironda_piloto_privado.whapi_inbox m USING(message_hmac)
 WHERE s.conversation_id=p_id AND (m.message_hmac IS NULL OR m.chat_hmac IS DISTINCT FROM p_chat_hmac OR m.participant_key IS DISTINCT FROM b OR m.plaintext_sha256 IS DISTINCT FROM s.source_sha256 OR m.kind IS DISTINCT FROM s.kind OR m.request_id IS NOT NULL))
 THEN RETURN jsonb_build_object('state','source_changed'); END IF;
 SELECT encode(sha256(convert_to(string_agg(s.message_hmac||':'||s.source_sha256||':'||s.kind,'|' ORDER BY s.received_at,s.message_hmac),'UTF8')),'hex') INTO manifest FROM cotironda_piloto_privado.v2_buyer_conversation_sources s WHERE s.conversation_id=p_id;
 IF manifest IS NULL THEN RETURN jsonb_build_object('state','source_changed'); END IF;
 SELECT * INTO old FROM cotironda_piloto_privado.v2_commercial_route_checkpoint WHERE conversation_id=p_id FOR UPDATE;
 IF old.conversation_id IS NOT NULL AND old.revision<>p_revision THEN
  DELETE FROM cotironda_piloto_privado.v2_commercial_route_checkpoint WHERE conversation_id=p_id;
  SELECT * INTO old FROM cotironda_piloto_privado.v2_commercial_route_checkpoint WHERE conversation_id=p_id;
 END IF;
 IF old.conversation_id IS NOT NULL AND (old.manifest_sha<>manifest OR old.expires_at<=clock_timestamp()) THEN RETURN jsonb_build_object('state','checkpoint_invalid'); END IF;
 IF p_action='load' THEN
  IF old.conversation_id IS NULL THEN RETURN jsonb_build_object('state','none','manifest',manifest); END IF;
  RETURN jsonb_build_object('state','snapshot','manifest',manifest,'cursor',old.cursor_no,'total',old.total_groups,'nonce',old.nonce,'ciphertext',old.ciphertext);
 END IF;
 IF p_manifest IS DISTINCT FROM manifest OR p_total IS NULL OR p_total NOT BETWEEN 1 AND 200 OR p_expected IS NULL OR p_expected NOT BETWEEN -1 AND 199 OR p_pause IS NULL
 OR p_nonce IS NULL OR p_nonce!~'^[A-Za-z0-9+/]{16}$' OR p_ciphertext IS NULL OR length(p_ciphertext) NOT BETWEEN 24 AND 16777216 OR p_ciphertext!~'^[A-Za-z0-9+/=]+$'
 THEN RETURN jsonb_build_object('state','invalid_snapshot'); END IF;
 cursor_next:=p_expected+1;
 IF cursor_next>p_total OR (p_pause AND cursor_next=p_total) OR (old.conversation_id IS NULL AND p_expected<>-1) OR (old.conversation_id IS NOT NULL AND (p_expected<>old.cursor_no OR p_total<>old.total_groups)) THEN RETURN jsonb_build_object('state','checkpoint_conflict'); END IF;
 IF EXISTS(SELECT 1 FROM cotironda_piloto_privado.ai_usage_calls_mvp264 WHERE participant_key=b AND state='reserved') THEN RETURN jsonb_build_object('state','meter_busy'); END IF;
 INSERT INTO cotironda_piloto_privado.v2_commercial_route_checkpoint(conversation_id,revision,manifest_sha,cursor_no,total_groups,nonce,ciphertext,expires_at)
 VALUES(p_id,p_revision,manifest,cursor_next,p_total,p_nonce,p_ciphertext,coalesce(old.expires_at,clock_timestamp()+interval '30 minutes'))
 ON CONFLICT(conversation_id) DO UPDATE SET cursor_no=excluded.cursor_no,nonce=excluded.nonce,ciphertext=excluded.ciphertext;
 IF p_pause THEN UPDATE cotironda_piloto_privado.v2_buyer_conversations SET state='collecting',lease=NULL,lease_until=NULL,ready_at=clock_timestamp()+interval '15 seconds' WHERE id=p_id; END IF;
 RETURN jsonb_build_object('state',CASE WHEN p_pause THEN 'queued' ELSE 'saved' END,'cursor',cursor_next);
END
$checkpoint$;
REVOKE ALL ON FUNCTION public.cotironda_piloto_v2_commercial_checkpoint(text,uuid,bigint,uuid,text,integer,integer,text,text,text,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cotironda_piloto_v2_commercial_checkpoint(text,uuid,bigint,uuid,text,integer,integer,text,text,text,boolean) TO service_role;
-- Mandatory before activation: delete checkpoint atomically with stage/finish, sweep expired rows using existing maintenance, bind AAD and source.

-- CANDIDATO: no instalar sin publicación autorizada del conjunto integrado.
-- Clone de RPC real: identidad, consentimiento, zona, catálogo y privacidad idénticos.
DO $commercial_catalogue$
DECLARE
 source_oid oid:=to_regprocedure('public.cotironda_piloto_ia_catalogo_mvp220(text,text)');
 def text;
 dest_oid oid;
BEGIN
 IF source_oid IS NULL THEN RAISE EXCEPTION 'catalogue source absent'; END IF;
 def:=pg_get_functiondef(source_oid);
 IF md5(def)<>'7404b7cca5f8a5ce64b39bae89cec2c0'
 OR (length(def)-length(replace(def,'IF v_suppliers>25 OR v_too_large THEN','')))/length('IF v_suppliers>25 OR v_too_large THEN')<>1
 OR (length(def)-length(replace(def,'public.cotironda_piloto_ia_catalogo_mvp220','')))/length('public.cotironda_piloto_ia_catalogo_mvp220')<>1
 THEN RAISE EXCEPTION 'catalogue source drift'; END IF;
 IF to_regprocedure('public.cotironda_piloto_v2_commercial_catalogue(text,text)') IS NOT NULL THEN RAISE EXCEPTION 'commercial catalogue already exists'; END IF;
 IF has_function_privilege('anon',source_oid,'EXECUTE') OR has_function_privilege('authenticated',source_oid,'EXECUTE') OR NOT has_function_privilege('service_role',source_oid,'EXECUTE') THEN RAISE EXCEPTION 'catalogue source ACL drift'; END IF;
 EXECUTE replace(replace(def,'public.cotironda_piloto_ia_catalogo_mvp220','public.cotironda_piloto_v2_commercial_catalogue'),'IF v_suppliers>25 OR v_too_large THEN','IF v_suppliers>200 OR v_too_large THEN');
 EXECUTE 'ALTER FUNCTION public.cotironda_piloto_v2_commercial_catalogue(text,text) OWNER TO postgres';
 EXECUTE 'REVOKE ALL ON FUNCTION public.cotironda_piloto_v2_commercial_catalogue(text,text) FROM PUBLIC, anon, authenticated';
 EXECUTE 'GRANT EXECUTE ON FUNCTION public.cotironda_piloto_v2_commercial_catalogue(text,text) TO service_role';
 dest_oid:=to_regprocedure('public.cotironda_piloto_v2_commercial_catalogue(text,text)');
 IF has_function_privilege('anon',dest_oid,'EXECUTE') OR has_function_privilege('authenticated',dest_oid,'EXECUTE') OR NOT has_function_privilege('service_role',dest_oid,'EXECUTE') THEN RAISE EXCEPTION 'commercial catalogue ACL mismatch'; END IF;
END
$commercial_catalogue$;

-- CANDIDATO NO INSTALADO; apply with checkpoint and worker as one authorized pilot release.
-- 32 is an upper technical bound ONLY for active commercial checkpoint. Ordinary reserve remains unchanged.
DO $pre$
DECLARE x record; f oid; 
BEGIN
 FOR x IN SELECT * FROM (VALUES ('public.cotironda_piloto_ai_usage_finish_mvp264(text,text,integer,text,text,integer,integer,integer,text)','4b44408f10327f4ff6d30e575244d889'),('public.cotironda_piloto_ai_usage_manual_review_mvp266(text,integer,uuid,text,text)','2e4862ecd372dddf62b2ecec37f3ec2b'),('public.cotironda_piloto_ai_usage_reserve_mvp264(text,text,integer,text)','3c3a6b21daaae8b4ec68e76906122235'),('public.cotironda_piloto_v2_conversation_meter(text,uuid,bigint,uuid)','94b2d4cb28b09a9d973b4f506e83a7dd')) a(sig,fp) LOOP
  f:=to_regprocedure(x.sig);
  IF f IS NULL OR md5(pg_get_functiondef(f))<>x.fp OR has_function_privilege('anon',f,'EXECUTE') OR has_function_privilege('authenticated',f,'EXECUTE') THEN RAISE EXCEPTION 'commercial meter source drift'; END IF;
 END LOOP;
 IF pg_get_constraintdef((SELECT oid FROM pg_constraint WHERE conrelid='cotironda_piloto_privado.ai_usage_calls_mvp264'::regclass AND conname='ai_usage_calls_mvp264_call_no_check')) IS DISTINCT FROM 'CHECK (((call_no >= 1) AND (call_no <= 8)))'
 OR pg_get_constraintdef((SELECT oid FROM pg_constraint WHERE conrelid='cotironda_piloto_privado.ai_usage_reviews_mvp266'::regclass AND conname='ai_usage_reviews_mvp266_call_no_check')) IS DISTINCT FROM 'CHECK (((call_no >= 1) AND (call_no <= 8)))'
 THEN RAISE EXCEPTION 'commercial ledger constraint drift'; END IF;
END $pre$;
ALTER TABLE cotironda_piloto_privado.ai_usage_calls_mvp264 DROP CONSTRAINT ai_usage_calls_mvp264_call_no_check, ADD CONSTRAINT ai_usage_calls_mvp264_call_no_check CHECK(call_no BETWEEN 1 AND 8 OR (participant_role='buyer' AND call_no BETWEEN 9 AND 32));
ALTER TABLE cotironda_piloto_privado.ai_usage_reviews_mvp266 DROP CONSTRAINT ai_usage_reviews_mvp266_call_no_check, ADD CONSTRAINT ai_usage_reviews_mvp266_call_no_check CHECK(call_no BETWEEN 1 AND 32);
-- Existing finish and manual review only affect a real reserved ledger row, not authorization of new calls.
DO $extend$
DECLARE x record; f oid; def text; acl aclitem[]; owner_oid oid;
BEGIN
 FOR x IN SELECT * FROM (VALUES ('public.cotironda_piloto_ai_usage_finish_mvp264(text,text,integer,text,text,integer,integer,integer,text)','4b44408f10327f4ff6d30e575244d889'),('public.cotironda_piloto_ai_usage_manual_review_mvp266(text,integer,uuid,text,text)','2e4862ecd372dddf62b2ecec37f3ec2b')) a(sig,fp) LOOP
  f:=to_regprocedure(x.sig);def:=pg_get_functiondef(f);
  SELECT proacl,proowner INTO acl,owner_oid FROM pg_proc WHERE oid=f;
  IF md5(def)<>x.fp OR (length(def)-length(replace(def,'p_call_no NOT BETWEEN 1 AND 8','')))/length('p_call_no NOT BETWEEN 1 AND 8')<>1 THEN RAISE EXCEPTION 'usage finish drift';END IF;
  EXECUTE replace(def,'p_call_no NOT BETWEEN 1 AND 8','p_call_no NOT BETWEEN 1 AND 32');
  IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=f AND proacl IS NOT DISTINCT FROM acl AND proowner=owner_oid) THEN RAISE EXCEPTION 'usage acl drift';END IF;
 END LOOP;
END $extend$;
CREATE OR REPLACE FUNCTION public.cotironda_piloto_v2_commercial_usage_reserve(p_message_hmac text, p_chat_hmac text, p_call_no integer, p_model text, p_id uuid, p_revision bigint, p_lease uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_person text;v_role text;n_ bigint;used_ bigint;unknown_ bigint;written_ int;
BEGIN
 IF p_message_hmac IS NULL OR p_message_hmac !~ '^[a-f0-9]{64}$'
 OR p_chat_hmac IS NULL OR p_chat_hmac !~ '^[a-f0-9]{64}$'
 OR p_call_no IS NULL OR p_call_no NOT BETWEEN 1 AND 32
 OR p_model IS NULL OR p_model NOT IN ('gpt-6-luna','gpt-6.1-sol')
 THEN RETURN jsonb_build_object('state','invalid');END IF;
 SELECT p.key,p.participant_role INTO v_person,v_role
 FROM cotironda_piloto_privado.whapi_inbox m
 JOIN cotironda_piloto_privado.participants p
  ON p.key=m.participant_key AND p.chat_hmac=m.chat_hmac
 WHERE m.message_hmac=p_message_hmac AND m.chat_hmac=p_chat_hmac
  AND p.consent_at IS NOT NULL AND p.opted_out_at IS NULL
  AND p.participant_role='buyer' AND EXISTS(
    SELECT 1 FROM cotironda_piloto_privado.ai_central_attempts_mvp226 b
    WHERE b.message_hmac=m.message_hmac AND b.buyer_key=p.key
     AND b.chat_hmac=m.chat_hmac AND b.state='reserved')
  AND EXISTS(
 SELECT 1 FROM cotironda_piloto_privado.v2_buyer_conversations g
 JOIN cotironda_piloto_privado.v2_commercial_route_checkpoint cp ON cp.conversation_id=g.id AND cp.revision=g.revision
 WHERE g.id=p_id AND g.buyer_key=p.key AND g.chat_hmac=p_chat_hmac
  AND g.revision=p_revision AND g.lease=p_lease AND g.state='processing'
  AND g.lease_until>clock_timestamp() AND g.request_id IS NULL
  AND cp.expires_at>clock_timestamp() AND cp.cursor_no<cp.total_groups
  AND m.message_hmac=(SELECT s.message_hmac FROM cotironda_piloto_privado.v2_buyer_conversation_sources s
   WHERE s.conversation_id=g.id ORDER BY s.received_at DESC,s.message_hmac DESC LIMIT 1)
)
 FOR UPDATE OF p;
 IF NOT FOUND THEN RETURN jsonb_build_object('state','not_authorized');END IF;
 -- Same lock ordering as checkpoint/claim: participant, then conversation.
 PERFORM 1 FROM cotironda_piloto_privado.v2_buyer_conversations g
 JOIN cotironda_piloto_privado.v2_commercial_route_checkpoint cp ON cp.conversation_id=g.id AND cp.revision=g.revision
 WHERE g.id=p_id AND g.buyer_key=v_person AND g.chat_hmac=p_chat_hmac AND g.revision=p_revision
 AND g.lease=p_lease AND g.state='processing' AND g.lease_until>clock_timestamp()
 AND g.request_id IS NULL AND cp.expires_at>clock_timestamp() AND cp.cursor_no<cp.total_groups
 AND p_message_hmac=(SELECT s.message_hmac FROM cotironda_piloto_privado.v2_buyer_conversation_sources s WHERE s.conversation_id=g.id ORDER BY s.received_at DESC,s.message_hmac DESC LIMIT 1)
 FOR UPDATE OF g;
 IF NOT FOUND THEN RETURN jsonb_build_object('state','stale');END IF;
 IF EXISTS(SELECT 1 FROM cotironda_piloto_privado.ai_usage_calls_mvp264 a
  WHERE a.message_hmac=p_message_hmac AND a.call_no=p_call_no)
 THEN RETURN jsonb_build_object('state','already_reserved');END IF;
 IF p_call_no<>(SELECT coalesce(max(a.call_no),0)+1 FROM cotironda_piloto_privado.ai_usage_calls_mvp264 a WHERE a.message_hmac=p_message_hmac)
 THEN RETURN jsonb_build_object('state','invalid_sequence');END IF;
 -- 24h rolling quotas are separate from persistent unreviewed uncertainty.
 SELECT count(*),
  coalesce(sum(CASE WHEN state='observed' THEN total_tokens ELSE 0 END),0)
 INTO n_,used_
 FROM cotironda_piloto_privado.ai_usage_calls_mvp264
 WHERE participant_key=v_person
  AND started_at>=clock_timestamp()-interval '24 hours';
 SELECT count(*) INTO unknown_
 FROM cotironda_piloto_privado.ai_usage_calls_mvp264 a
 WHERE a.participant_key=v_person AND a.state IN('reserved','unmetered')
  AND NOT EXISTS(
   SELECT 1 FROM cotironda_piloto_privado.ai_usage_reviews_mvp266 r
   WHERE r.message_hmac=a.message_hmac AND r.call_no=a.call_no
  );
 -- 24 calls maximum per person/24h AND no fresh paid call while previous
 -- request is of UNKNOWN spend. Includes network timeouts and missing usage.
 IF unknown_>0 THEN RETURN jsonb_build_object('state','usage_unknown_blocked');END IF;
 -- Llamadas sin tope artificial; proteger el consumo real de tokens.
 -- Un consumo desconocido bloquea nuevas llamadas hasta su revision.
 IF used_>=200000
 THEN RETURN jsonb_build_object('state','budget_exceeded');END IF;
 INSERT INTO cotironda_piloto_privado.ai_usage_calls_mvp264(
  message_hmac,call_no,participant_key,participant_role,model_code)
 VALUES(p_message_hmac,p_call_no,v_person,v_role,p_model)
 ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS written_=row_count;
 RETURN jsonb_build_object('state',CASE WHEN written_=1 THEN 'reserved'
  ELSE 'already_reserved' END);
END;$function$;
REVOKE ALL ON FUNCTION public.cotironda_piloto_v2_commercial_usage_reserve(text,text,integer,text,uuid,bigint,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cotironda_piloto_v2_commercial_usage_reserve(text,text,integer,text,uuid,bigint,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.cotironda_piloto_v2_commercial_meter(p_chat_hmac text, p_id uuid, p_revision bigint, p_lease uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE g record; m record; b text; prev record; n integer;
BEGIN
 SELECT key INTO b FROM cotironda_piloto_privado.participants WHERE chat_hmac=p_chat_hmac AND participant_role='buyer' AND consent_at IS NOT NULL AND opted_out_at IS NULL FOR UPDATE;
 IF b IS NULL THEN RETURN jsonb_build_object('state','not_authorized'); END IF;
 SELECT * INTO g FROM cotironda_piloto_privado.v2_buyer_conversations WHERE id=p_id AND buyer_key=b AND chat_hmac=p_chat_hmac AND state='processing' AND revision=p_revision AND lease=p_lease AND lease_until>clock_timestamp() FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('state','stale');END IF;
 SELECT s.message_hmac,s.source_sha256 INTO m FROM cotironda_piloto_privado.v2_buyer_conversation_sources s JOIN cotironda_piloto_privado.whapi_inbox i USING(message_hmac)
 WHERE s.conversation_id=p_id AND i.participant_key=b AND i.chat_hmac=p_chat_hmac AND i.plaintext_sha256=s.source_sha256 AND i.request_id IS NULL
 ORDER BY s.received_at DESC,s.message_hmac DESC LIMIT 1;
 IF NOT FOUND THEN RETURN jsonb_build_object('state','source_changed');END IF;
 -- Si otra revisión todavía tiene una llamada abierta, no competir por tokens.
 IF EXISTS(SELECT 1 FROM cotironda_piloto_privado.ai_usage_calls_mvp264 u WHERE u.participant_key=b AND u.state='reserved')
 THEN
  UPDATE cotironda_piloto_privado.v2_buyer_conversations SET state='collecting',lease=NULL,lease_until=NULL,ready_at=clock_timestamp()+interval '15 seconds' WHERE id=p_id;
  RETURN jsonb_build_object('state','meter_busy');
 END IF;
 SELECT * INTO prev FROM cotironda_piloto_privado.ai_central_attempts_mvp226 WHERE message_hmac=m.message_hmac FOR UPDATE;
 IF FOUND AND (prev.buyer_key IS DISTINCT FROM b OR prev.chat_hmac IS DISTINCT FROM p_chat_hmac OR prev.source_sha256 IS DISTINCT FROM m.source_sha256 OR prev.state<>'reserved')
 THEN RETURN jsonb_build_object('state','attempt_not_eligible');END IF;
 IF NOT FOUND THEN
  INSERT INTO cotironda_piloto_privado.ai_central_attempts_mvp226(message_hmac,buyer_key,chat_hmac,source_sha256) VALUES(m.message_hmac,b,p_chat_hmac,m.source_sha256);
 END IF;
 SELECT coalesce(max(call_no),0) INTO n FROM cotironda_piloto_privado.ai_usage_calls_mvp264 WHERE message_hmac=m.message_hmac;
 IF NOT EXISTS(SELECT 1 FROM cotironda_piloto_privado.v2_commercial_route_checkpoint cp WHERE cp.conversation_id=g.id AND cp.revision=g.revision AND cp.expires_at>clock_timestamp())
 THEN RETURN jsonb_build_object('state','checkpoint_missing');END IF;
 IF n>=32 THEN RETURN jsonb_build_object('state','meter_exhausted');END IF;
 RETURN jsonb_build_object('state','reserved','message_hmac',m.message_hmac,'usage_call_no',n,'max_calls',32,'lease_until_ms',floor(extract(epoch FROM g.lease_until)*1000)::bigint);
END $function$;
REVOKE ALL ON FUNCTION public.cotironda_piloto_v2_commercial_meter(text,uuid,bigint,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cotironda_piloto_v2_commercial_meter(text,uuid,bigint,uuid) TO service_role;

-- CANDIDATO NO INSTALADO. Ejecutar únicamente como parte del release piloto autorizado y completo.
-- Las 2 funciones se sustituyen atómicamente por CREATE OR REPLACE; no cambia firmas ni ACL.
DO $capacity$
DECLARE x record; current_def text; next_def text; fn oid; old_acl aclitem[]; old_owner oid;
BEGIN
 FOR x IN SELECT * FROM (VALUES
('public.cotironda_piloto_v2_conversation_stage(text,uuid,bigint,uuid,jsonb,text,jsonb,jsonb,jsonb,jsonb)','b0a2363b70306c07cb518dc73c97cac4','IF v_line_count NOT BETWEEN 1 AND 25 OR jsonb_array_length(p_destinos) NOT BETWEEN 1 AND 25','IF v_line_count NOT BETWEEN 1 AND 25 OR jsonb_array_length(p_destinos) NOT BETWEEN 1 AND 70'),
('public.cotironda_piloto_ia_publish_mvp222(uuid)','8c14f3a39b2c22a9f2d9b0b5e0c06783','IF v_supplier_count NOT BETWEEN 1 AND 25 OR v_pairs>625','IF v_supplier_count NOT BETWEEN 1 AND 70 OR v_pairs>1750
  OR ((v_supplier_count>25 OR v_pairs>625) AND NOT (
   (v_round.timing_mode IS NOT DISTINCT FROM ''business_two_days''
    AND v_round.round_days IS NOT DISTINCT FROM 2
    AND v_round.v2_calendar_revision IS NOT NULL
    AND cotironda_piloto_privado.v2_conversation_source_verified(v_round.id)) IS TRUE))')
 ) p(signature,expected,old_text,new_text) LOOP
  fn:=to_regprocedure(x.signature);
  IF fn IS NULL THEN RAISE EXCEPTION 'capacity candidate missing function'; END IF;
  SELECT proacl,proowner INTO old_acl,old_owner FROM pg_proc WHERE oid=fn;
  current_def:=pg_get_functiondef(fn);
  IF md5(current_def)<>x.expected OR (length(current_def)-length(replace(current_def,x.old_text,'')))/length(x.old_text)<>1 THEN RAISE EXCEPTION 'capacity candidate fingerprint mismatch'; END IF;
  IF has_function_privilege('anon',fn,'EXECUTE') OR has_function_privilege('authenticated',fn,'EXECUTE') OR NOT has_function_privilege('service_role',fn,'EXECUTE') THEN RAISE EXCEPTION 'capacity candidate ACL mismatch'; END IF;
  next_def:=replace(current_def,x.old_text,x.new_text);
  EXECUTE next_def;
  IF NOT EXISTS (SELECT 1 FROM pg_proc WHERE oid=fn AND proacl IS NOT DISTINCT FROM old_acl AND proowner=old_owner) THEN RAISE EXCEPTION 'capacity candidate ACL changed'; END IF;
 END LOOP;
END
$capacity$;

-- After stage-capacity and history candidates. Wrapper keeps commercial metadata in the same transaction.
CREATE FUNCTION public.cotironda_piloto_v2_commercial_stage(p_buyer_chat_hmac text,p_id uuid,p_revision bigint,p_lease uuid,p_fragments jsonb,p_city text,p_items jsonb,p_destinos jsonb,p_payment jsonb,p_vat jsonb,p_rubros jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $commercial_stage$
DECLARE v jsonb; req uuid; cp cotironda_piloto_privado.v2_commercial_route_checkpoint%ROWTYPE; b text;
BEGIN
 IF jsonb_typeof(p_rubros) IS DISTINCT FROM 'array' OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_typeof(p_destinos) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rubros)<>jsonb_array_length(p_items) OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_rubros) x WHERE x<>'null'::jsonb AND (jsonb_typeof(x)<>'string' OR x#>>'{}' NOT IN ('corralon','hormigon_elaborado','hierros_aceros','construccion_seca','electricidad','sanitarios_gas','maderas','pintureria_tecnica','techos_aislantes','ferreteria'))) THEN RETURN jsonb_build_object('state','invalid_rubros'); END IF;
 SELECT key INTO b FROM cotironda_piloto_privado.participants WHERE chat_hmac=p_buyer_chat_hmac AND participant_role='buyer' AND consent_at IS NOT NULL AND opted_out_at IS NULL FOR UPDATE;
 IF b IS NULL THEN RETURN jsonb_build_object('state','not_authorized'); END IF;
 PERFORM 1 FROM cotironda_piloto_privado.v2_buyer_conversations g WHERE g.id=p_id AND g.buyer_key=b AND g.chat_hmac=p_buyer_chat_hmac AND g.state='processing' AND g.revision=p_revision AND g.lease=p_lease AND g.lease_until>clock_timestamp() FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('state','stale'); END IF;
 SELECT * INTO cp FROM cotironda_piloto_privado.v2_commercial_route_checkpoint WHERE conversation_id=p_id FOR UPDATE;
 IF (cp.conversation_id IS NULL AND jsonb_array_length(p_destinos)>7) OR (cp.conversation_id IS NOT NULL AND (cp.revision<>p_revision OR cp.cursor_no<>cp.total_groups OR cp.expires_at<=clock_timestamp())) THEN RETURN jsonb_build_object('state','checkpoint_not_complete'); END IF;
 v:=public.cotironda_piloto_v2_conversation_stage(p_buyer_chat_hmac,p_id,p_revision,p_lease,p_fragments,p_city,p_items,p_destinos,p_payment,p_vat);
 IF v->>'state'='shadow_staged' THEN
  req:=(v->>'request_id')::uuid;
  INSERT INTO cotironda_piloto_privado.v2_commercial_request_rubros_d013(request_id,line_no,rubro)
  SELECT req,ord::smallint,x#>>'{}' FROM jsonb_array_elements(p_rubros) WITH ORDINALITY AS a(x,ord) WHERE x<>'null'::jsonb;
  DELETE FROM cotironda_piloto_privado.v2_commercial_route_checkpoint WHERE conversation_id=p_id;
 END IF;
 RETURN v;
END $commercial_stage$;
REVOKE ALL ON FUNCTION public.cotironda_piloto_v2_commercial_stage(text,uuid,bigint,uuid,jsonb,text,jsonb,jsonb,jsonb,jsonb,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cotironda_piloto_v2_commercial_stage(text,uuid,bigint,uuid,jsonb,text,jsonb,jsonb,jsonb,jsonb,jsonb) TO service_role;
CREATE FUNCTION cotironda_piloto_privado.v2_commercial_checkpoint_cleanup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $cleanup$
BEGIN
 IF NEW.revision IS DISTINCT FROM OLD.revision OR NEW.state IN ('review','done') THEN
  DELETE FROM cotironda_piloto_privado.v2_commercial_route_checkpoint WHERE conversation_id=NEW.id;
 END IF;
 RETURN NEW;
END $cleanup$;
REVOKE ALL ON FUNCTION cotironda_piloto_privado.v2_commercial_checkpoint_cleanup() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER v2_commercial_checkpoint_cleanup AFTER UPDATE OF revision,state ON cotironda_piloto_privado.v2_buyer_conversations FOR EACH ROW EXECUTE FUNCTION cotironda_piloto_privado.v2_commercial_checkpoint_cleanup();
